import RNA, random, sys, time
target="(.(..((.(((.(((.((....).))).)))).).)..))"
n=len(target)
stack=[]; pair=[-1]*n
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pair[i]=j; pair[j]=i
def pairs(s):
    st=[];p=set()
    for i,c in enumerate(s):
        if c=='(':st.append(i)
        elif c==')':p.add((st.pop(),i))
    return p
pa=pairs(target)
# caps: hairpin closing (17,22) -> GAAA at 18..21
caps={(17,22):"GAAA"}
locked=set()
for (i,j),m in caps.items():
    for k,ch in enumerate(m): locked.add(i+1+k)

def init():
    seq=['A']*n
    for i in range(n):
        if pair[i]!=-1 and i<pair[i]:
            seq[i]='G'; seq[pair[i]]='C'
    for (i,j),m in caps.items():
        for k,ch in enumerate(m): seq[i+1+k]=ch
    return seq

def score(seq):
    s="".join(seq)
    fc=RNA.fold_compound(s); mfe,e=fc.mfe()
    pm=pairs(mfe)
    return len(pa^pm),e

seq=init()
bd,be=score(seq)
print("init",bd,be, file=sys.stderr)
best=seq[:]
random.seed(2)
t0=time.time()
iters=0
while bd>0 and time.time()-t0<60:
    cur="".join(best)
    fc=RNA.fold_compound(cur); mfe,e=fc.mfe()
    pm=pairs(mfe)
    miss=pa-pm; spur=pm-pa
    bad=set()
    for (i,j) in list(miss)+list(spur):
        bad.add(i); bad.add(j)
    cand=[p for p in range(n) if p not in locked]
    if bad and random.random()<0.7:
        p=random.choice(list(bad))
    else:
        p=random.choice(cand)
    old=best[p]
    newb=random.choice("ACGU")
    if newb==old: continue
    best[p]=newb
    d,e=score(best)
    if d<bd or (d==bd and e<be):
        bd,be=d,e
    else:
        if random.random()<0.05: pass
        else: best[p]=old
    iters+=1
print("FINAL",bd,be,iters, file=sys.stderr)
print("".join(best))
